import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"PlaceholderAPI 占位符","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/placeholders.md","filePath":"modules/storage/placeholders.md","lastUpdated":null}'),r={name:"modules/storage/placeholders.md"};function l(c,t,s,i,h,_){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="placeholderapi-占位符" tabindex="-1">PlaceholderAPI 占位符 <a class="header-anchor" href="#placeholderapi-占位符" aria-label="Permalink to &quot;PlaceholderAPI 占位符&quot;">​</a></h1><p>EmakiStorage 在安装 PlaceholderAPI 时注册扩展，标识符为 <code>emakistorage</code>。占位符适用于计分板、菜单、聊天格式、BossBar、ActionBar 以及支持 PlaceholderAPI 的其他插件文本模板。</p><p>如果 PlaceholderAPI 未安装，EmakiStorage 本体仍然可以正常运行，只是不会注册 <code>%emakistorage_*%</code> 外部占位符。</p><h2 id="占位符列表" tabindex="-1">占位符列表 <a class="header-anchor" href="#占位符列表" aria-label="Permalink to &quot;占位符列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>占位符</th><th>说明</th></tr></thead><tbody><tr><td><code>%emakistorage_used_slots%</code></td><td>已占用槽位数。</td></tr><tr><td><code>%emakistorage_total_slots%</code></td><td>有效槽位总数。</td></tr><tr><td><code>%emakistorage_free_slots%</code></td><td>剩余空槽数。</td></tr><tr><td><code>%emakistorage_purchased_slots%</code></td><td>已购买槽位数。</td></tr><tr><td><code>%emakistorage_granted_slots%</code></td><td>授予槽位数。</td></tr><tr><td><code>%emakistorage_pages%</code></td><td>总页数。</td></tr><tr><td><code>%emakistorage_stack_limit%</code></td><td>当前生效的玩家级单槽上限。</td></tr><tr><td><code>%emakistorage_sort_mode%</code></td><td>当前排序模式 id。</td></tr><tr><td><code>%emakistorage_total_amount%</code></td><td>所有条目数量之和，溢出时饱和为 <code>Long.MAX_VALUE</code>。</td></tr><tr><td><code>%emakistorage_count_&lt;token&gt;%</code></td><td>指定 ItemSource token 的存量，无此条目时为 <code>0</code>。</td></tr></tbody></table><h2 id="求值线程与未载入数据" tabindex="-1">求值线程与未载入数据 <a class="header-anchor" href="#求值线程与未载入数据" aria-label="Permalink to &quot;求值线程与未载入数据&quot;">​</a></h2><p>所有占位符都读取在线玩家的内存数据，不做磁盘载入：占位符会在 PAPI 调用它的任意线程上求值，阻塞 IO 不可接受。玩家数据未载入时返回 <code>0</code>，无法识别的占位符返回空字符串。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./capacity.html">容量与缩容</a>：<code>total_slots</code>、<code>purchased_slots</code> 等数值背后的四来源容量模型。</li><li><a href="./events.html">事件 API</a>：需要拦截而不只是读取时使用的 Bukkit 事件。</li><li><a href="./api.html">API 与集成</a>：在代码中读取容量与存量的方式。</li></ul>',9)])])}const p=e(r,[["render",l]]);export{m as __pageData,p as default};
